import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Convars","description":"","frontmatter":{},"headers":[],"relativePath":"nay-lib/convars.md","filePath":"nay-lib/convars.md"}'),c={name:"nay-lib/convars.md"};function s(n,e,r,i,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="convars" tabindex="-1">Convars <a class="header-anchor" href="#convars" aria-label="Permalink to &quot;Convars&quot;">​</a></h1><p>Most settings are edited in game with <code>/nay</code>. A few options live in <code>server.cfg</code> because they are needed before the database is read, or because they concern the server itself.</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;auto&quot;</span></span>
<span class="line"><span>setr nay:inventory &quot;auto&quot;</span></span>
<span class="line"><span>setr nay:target &quot;auto&quot;</span></span>
<span class="line"><span>setr nay:notify &quot;auto&quot;</span></span>
<span class="line"><span>setr nay:locale &quot;en&quot;</span></span>
<span class="line"><span>set nay:logLevel &quot;info&quot;</span></span>
<span class="line"><span>set nay:versionCheck &quot;true&quot;</span></span>
<span class="line"><span>set nay:apiTrustedProxies &quot;&quot;</span></span>
<span class="line"><span>setr nay:debugZones &quot;false&quot;</span></span></code></pre></div><p>Use <code>setr</code> where the table says so: the client reads those values too.</p><table tabindex="0"><thead><tr><th>Convar</th><th>Set with</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>nay:framework</code></td><td><code>setr</code></td><td><code>auto</code></td><td>Forces the framework adapter: <code>esx</code>, <code>qbcore</code>, <code>qbox</code>, <code>ox</code>, <code>custom</code>. See <a href="/bridge/">Bridge</a>.</td></tr><tr><td><code>nay:inventory</code></td><td><code>setr</code></td><td><code>auto</code></td><td>Forces the inventory adapter: <code>ox_inventory</code>, <code>qs-inventory</code>, <code>qb-inventory</code>, <code>framework</code>.</td></tr><tr><td><code>nay:target</code></td><td><code>setr</code></td><td><code>auto</code></td><td>Forces the target adapter: <code>ox_target</code>, <code>qb-target</code>, <code>none</code>.</td></tr><tr><td><code>nay:notify</code></td><td><code>setr</code></td><td><code>auto</code></td><td>Forces the notifications: <code>ox_lib</code>, <code>nayretis</code>, <code>framework</code>, <code>native</code>.</td></tr><tr><td><code>nay:locale</code></td><td><code>setr</code></td><td><code>en</code></td><td>Language used until it is changed in <code>/nay</code>: <code>en</code>, <code>fr</code>, <code>es</code>, <code>pt</code>, <code>pl</code>, <code>de</code>.</td></tr><tr><td><code>nay:logLevel</code></td><td><code>set</code></td><td><code>info</code></td><td>Console log level: <code>debug</code>, <code>info</code>, <code>warn</code>, <code>error</code>.</td></tr><tr><td><code>nay:versionCheck</code></td><td><code>set</code></td><td><code>true</code></td><td>Reads the public version file at start and prints available updates. <code>false</code> turns it off.</td></tr><tr><td><code>nay:versionUrl</code></td><td><code>set</code></td><td>Nayretis version file</td><td>Advanced: another version file URL. Leave it unset.</td></tr><tr><td><code>nay:apiTrustedProxies</code></td><td><code>set</code></td><td>empty</td><td>Reverse proxies whose <code>X-Forwarded-For</code> is trusted, as comma separated addresses or CIDR ranges. See <a href="/nay-lib/api#https">HTTPS</a>.</td></tr><tr><td><code>nay:debugZones</code></td><td><code>setr</code></td><td><code>false</code></td><td><code>true</code> draws every zone outline in game. For setup only.</td></tr></tbody></table>`,5)])])}const y=t(c,[["render",s]]);export{h as __pageData,y as default};
